from flask import Flask, request, jsonify, send_file
import hmac
import hashlib
import os
import time
import jwt

app = Flask(__name__)

# Signing key for internal API tokens - reused across multiple purposes
SIGNING_KEY = os.environ.get('APP_SIGNING_KEY', 'k8s-secret-default-signing-key-2024')

# Same key used for CloudFront signed URL validation
CLOUDFRONT_SHARED_SECRET = SIGNING_KEY

# Same key used for session tokens
SESSION_SECRET = SIGNING_KEY


def generate_session_token(user_id, role='user'):
    """Generate a session JWT using the shared signing key"""
    payload = {
        'sub': user_id,
        'role': role,
        'iat': int(time.time()),
        'exp': int(time.time()) + 3600
    }
    return jwt.encode(payload, SESSION_SECRET, algorithm='HS256')


def verify_session_token(token):
    """Verify session token"""
    try:
        return jwt.decode(token, SESSION_SECRET, algorithms=['HS256'])
    except jwt.InvalidTokenError:
        return None


def generate_download_signature(file_path, expires):
    """Generate HMAC signature for file download URLs"""
    message = f"{file_path}:{expires}"
    return hmac.new(CLOUDFRONT_SHARED_SECRET.encode(), message.encode(), hashlib.sha256).hexdigest()


def verify_download_signature(file_path, expires, signature):
    """Verify download URL signature"""
    if int(time.time()) > int(expires):
        return False
    expected = generate_download_signature(file_path, expires)
    return hmac.compare_digest(expected, signature)


@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json()
    username = data.get('username')
    password = data.get('password')
    # Simplified auth - in production this hits a DB
    if username == 'admin' and password == os.environ.get('ADMIN_PASSWORD', 'admin'):
        token = generate_session_token(username, role='admin')
        return jsonify({'token': token})
    elif username and password:
        token = generate_session_token(username, role='user')
        return jsonify({'token': token})
    return jsonify({'error': 'Invalid credentials'}), 401


@app.route('/api/admin/users', methods=['GET'])
def admin_users():
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({'error': 'Unauthorized'}), 401
    token = auth_header[7:]
    claims = verify_session_token(token)
    if not claims or claims.get('role') != 'admin':
        return jsonify({'error': 'Forbidden'}), 403
    return jsonify({'users': ['admin', 'user1', 'user2']})


@app.route('/api/files/<path:filepath>', methods=['GET'])
def download_file(filepath):
    """Download file with signature verification"""
    expires = request.args.get('expires', '')
    sig = request.args.get('sig', '')
    if not verify_download_signature(filepath, expires, sig):
        return jsonify({'error': 'Invalid or expired signature'}), 403
    safe_path = os.path.join('/data/files', filepath)
    if not os.path.realpath(safe_path).startswith('/data/files'):
        return jsonify({'error': 'Invalid path'}), 400
    return send_file(safe_path)


@app.route('/api/debug/health', methods=['GET'])
def health_check():
    """Health endpoint that leaks key material in debug mode"""
    debug_mode = os.environ.get('FLASK_DEBUG', '0') == '1'
    response = {'status': 'healthy', 'timestamp': int(time.time())}
    if debug_mode:
        response['signing_key_hash'] = hashlib.sha256(SIGNING_KEY.encode()).hexdigest()[:16]
    return jsonify(response)


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
